import{_ as t,o as i,c as o,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Playwright E2E Testing Rules","description":"Strict rules regarding End-to-End (E2E) testing with Playwright to prevent data pollution in the production database.","frontmatter":{"isInternal":true,"type":"Architecture Decision Record","title":"Playwright E2E Testing Rules","description":"Strict rules regarding End-to-End (E2E) testing with Playwright to prevent data pollution in the production database.","tags":["testing","playwright","e2e","ci-cd","architecture-decision-record"]},"headers":[],"relativePath":"adr/playwright-e2e-testing-rules.md","filePath":"adr/playwright-e2e-testing-rules.md"}'),n={name:"adr/playwright-e2e-testing-rules.md"};function a(r,e,l,c,d,u){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="playwright-e2e-testing-rules" tabindex="-1">Playwright E2E Testing Rules <a class="header-anchor" href="#playwright-e2e-testing-rules" aria-label="Permalink to &quot;Playwright E2E Testing Rules&quot;">​</a></h1><p>This document outlines the strict rules regarding End-to-End (E2E) testing with Playwright in this repository to prevent data pollution in the production database.</p><h2 id="environment-architecture-context" tabindex="-1">Environment Architecture Context <a class="header-anchor" href="#environment-architecture-context" aria-label="Permalink to &quot;Environment Architecture Context&quot;">​</a></h2><ol><li><strong>Local Development &amp; Testing:</strong> Whenever you run tests locally (both E2E Playwright tests and Vitest Unit tests), they MUST run against the <strong>Firebase Emulators</strong> (<code>http://localhost:5173</code>). It is completely safe to write data here.</li><li><strong>GitHub CI (PRs &amp; Staging):</strong> When tests run in GitHub Actions, they run against the live <code>sanjeev-ai-staging</code> Firebase project. We bypass Google Auth using <strong>Firebase Admin Custom Tokens</strong> (<code>e2e-test-user</code>). Safe to write data (it&#39;s a test environment).</li><li><strong>GitHub CI (Production):</strong> Runs against the live <code>sanjeev-ai</code> Firebase project using Custom Tokens for Smoke Testing. <strong>EXTREMELY DANGEROUS TO WRITE DATA.</strong></li></ol><h2 id="🤖-ai-instructions" tabindex="-1">🤖 AI Instructions <a class="header-anchor" href="#🤖-ai-instructions" aria-label="Permalink to &quot;🤖 AI Instructions&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>CRITICAL RULE FOR AI AGENTS &amp; DEVELOPERS:</strong> Do NOT write Playwright tests that create dummy user accounts, upload fake videos, or execute heavy database writes unless they are explicitly gated behind an environment check or strictly limited to Staging.</p></div><p>If a test executes on the <code>main</code> branch (Production deployment), it is hitting the real production database. We currently rely on a simple read-only &quot;Smoke Test&quot; that just verifies the app renders without crashing.</p><p><strong>When writing new Playwright tests:</strong></p><ul><li>Always ensure test tear-down logic deletes any documents created.</li><li>For write-heavy flows, test them thoroughly in <code>staging</code> and <strong>MUST</strong> skip them in the <code>main</code> (Prod) pipeline to avoid analytics pollution, API billing costs, and production data contamination.</li><li><strong>AI Mocking:</strong> AI API responses (Vertex, Imagen, ElevenLabs) MUST be mocked in <code>local/dev</code> environments to keep tests fast and cheap. Tests running in the <code>staging</code> environment should hit real endpoints to verify integration fidelity.</li><li><strong>Emulator Verification</strong>: Whenever an E2E test fails and you attempt to fix it, you MUST verify the fix by running the test locally against the Firebase Emulators (<code>npx playwright test</code>). Do not guess a fix and commit blindly.</li><li><strong>Failure States:</strong> Explicitly cover critical failure states (e.g., YouTube API timeouts, insufficient billing credits) to ensure the UI degrades gracefully.</li></ul><h2 id="flakiness-lessons-learned-july-2026" tabindex="-1">Flakiness Lessons Learned (July 2026) <a class="header-anchor" href="#flakiness-lessons-learned-july-2026" aria-label="Permalink to &quot;Flakiness Lessons Learned (July 2026)&quot;">​</a></h2><p>The following rules were discovered during E2E test remediation and are now codified in the dedicated skill file.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Emoji Locator Bug:</strong> Playwright&#39;s <code>getByRole</code> accessible name matching breaks on buttons containing emoji characters (e.g., <code>✏️ Open Metadata Editor</code>). Use <code>page.locator(&#39;button&#39;, { hasText: &#39;...&#39; })</code> instead.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Modal Occlusion:</strong> <code>toBeVisible()</code> fails if an element is rendered behind a modal backdrop. Use <code>toBeAttached()</code> or <code>waitForFunction</code> with raw DOM text checks instead.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Mock Data Integrity:</strong> All Firestore mock documents MUST include relational foreign keys (e.g., <code>scriptId</code>) that the frontend uses in <code>where()</code> queries. Omitting these causes the frontend listener to return empty, making the entire test proceed with null data silently.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Emulator Race Conditions:</strong> Firebase emulator backend functions execute instantly. Assertions on intermediate workflow states (e.g., <code>&#39;queued&#39;</code>) will fail because the backend has already processed the state to <code>&#39;running&#39;</code> or <code>&#39;error&#39;</code>. Accept any downstream state in assertions.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Emulator Project ID Mismatch:</strong> Emulators must be executed specifically against the local project ID (<code>--project sanjeev-ai</code>). If executed from the root without it, or if there&#39;s a mismatch between the frontend&#39;s <code>VITE_FIREBASE_PROJECT_ID</code> and the emulator execution, Firestore writes will be directed to the wrong project namespace and fail silently.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Cloud Function State Overwrite:</strong> When a test writes a document that triggers a cloud function (like <code>onWorkflowCreated</code>), if the test immediately tries to override state on a child document (e.g., <code>workflowState</code>), the cloud function might fire <em>after</em> the test writes, overwriting the test&#39;s manual override. Tests must <code>waitForTimeout</code> after a trigger event before seeding manual state overrides.</p></div><h2 id="cross-references" tabindex="-1">Cross-References <a class="header-anchor" href="#cross-references" aria-label="Permalink to &quot;Cross-References&quot;">​</a></h2><ul><li><strong>Dedicated Skill:</strong> <code>.agents/skills/e2e-testing-playwright/SKILL.md</code> — comprehensive rules with code examples.</li><li><strong>Frontend Guidelines:</strong> <code>docs/specs/frontend-guidelines.md</code> §6 (Unit Testing &amp; Testability).</li><li><strong>E2E Use Cases:</strong> <code>docs/testing/e2e-use-cases.md</code>.</li></ul>',19)])])}const p=t(n,[["render",a]]);export{h as __pageData,p as default};
